window.__saqPaperQuestions("2021-1-pah",[{"number":1,"title":"","stemText":"A 10 year old girl has presented with a fever and cough.\nA chest x-ray is provided below.","parts":[{"id":"a","label":"Part A","prompt":"State the pathology demonstrated, with 3 supportive radiographic findings. (4 marks) Pathology Supportive findings 1) 2) 3)"},{"id":"b","label":"Part B","prompt":"List the 3 most likely causative organisms for this problem. (3 marks)\n1) 2) 3)"},{"id":"c","label":"Part C","prompt":"State 5 possible indications for admission to hospital. (5 marks)\n1) 2) 3) 4) 5)"}],"propPages":["asset:img74d24f712080eacd8a"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Pneumonia – lingular and also right sided peri-hilar</td></tr><tr><td>-</td><td>Consolidation Left lower zone</td></tr><tr><td>-</td><td>Obscuring of left heart border</td></tr><tr><td>-</td><td>Patchy consolidation right perihilar area</td></tr><tr><td>-</td><td>Air bronchograms</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Viral (one of Adeno/Influen/Parainfluen/RSV/HMPV)</div><div class=\"answer-line\">Mycoplasma pneumoniae</div><div class=\"answer-line\">Accept Chlamydia Pneumoniae</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Many here:</div><div class=\"answer-line\">Systemically unwell eg shock</div><div class=\"answer-line\"><strong>Oxygen requirement </strong></div><div class=\"answer-line\">Failure outpatient treatment</div><div class=\"answer-line\">Poor oral intake</div><div class=\"answer-line\">Any good social reason (but just one of these)</div><div class=\"answer-line\">Significant co-morbidity eg congenital heart disease</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 30 year old woman has been brought to the ED after an attempted strangulation by her domestic partner.","parts":[{"id":"a","label":"Part A","prompt":"List 4 examination findings that would justify performing a CT angiogram of her neck.\n(4 marks) 1) 2) 3) 4) There are no significant physical injuries on assessment. The patient has significant emotional distress."},{"id":"b","label":"Part B","prompt":"List 4 factors, in general, that place a patient at a higher risk of being the victim of\ndomestic violence. (4 marks) 1) 2) 3) 4)"},{"id":"c","label":"Part C","prompt":"State 4 aspects of your management of this situation. Include the desired outcome for\neach aspect. (4 marks) 1) 2) 3) 4)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Carotid bruit</div><div class=\"answer-line\">Focal neurological abnormality</div><div class=\"answer-line\">Horner’s syndrome</div><div class=\"answer-line\">Hoarse voice</div><div class=\"answer-line\">Haematoma – large / pulsatile / expanding</div><div class=\"answer-line\">Significant ligature mark</div><div class=\"answer-line\">Altered Conscious state</div><div class=\"answer-line\">Subcutaneous emphysema</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Female</div><div class=\"answer-line\">Drug / alcohol misuse</div><div class=\"answer-line\">Minority ethnic groups</div><div class=\"answer-line\">Low socio-economic background</div><div class=\"answer-line\">Poor social supports/geographic isolation</div><div class=\"answer-line\">Disability</div><div class=\"answer-line\">Many others likely to be accepted</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Analgesia – simple – paracetamol 1g, ibuprofen 400mg until confortable</div><div class=\"answer-line\">Discharge planning - Safe accommodation sorted</div><div class=\"answer-line\">Counselling / empathy – to generate rapport and facilitate best possible outcome</div><div class=\"answer-line\">Police involvement if pt wishes to advocate for safest outcome</div><div class=\"answer-line\">Offer to contact a support person/friend – to provide emotional support</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 56 year old woman has been brought to hospital with 6 hours of central chest pain.\nAn ECG is provided below.","parts":[{"id":"a","label":"Part A","prompt":"State the diagnosis, with 4 supportive abnormalities on the ECG. (5 marks) Diagnosis Supportive abnormalities 1) 2) 3) 4)"},{"id":"b","label":"Part B","prompt":"List 5 complications of this pathology that this patient might experience during her time in the ED. (5 marks) 1) 2) 3) 4) 5) Your assessment has revealed the following vital signs:\n\nGCS\n\nBP\n75/45 mmHg O2 sats 100% room air"},{"id":"c","label":"Part C","prompt":"State 6 components of your management of this patient. (6 marks)\n1) 2) 3) 4) 5) 6)"}],"propPages":["asset:imgdbca9e82aedb5b8f2b"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Inferior ST Elevation with STE in III &gt; II – likely RV infarction</div><div class=\"answer-line\">Q waves in inferior leads</div><div class=\"answer-line\">ST Depression in aVL 2mm</div><div class=\"answer-line\">ST Depression with abnormal (early) R waves and upright T waves in V1-3 consistent with posterior</div><div class=\"answer-line\">STEMI</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">AV Block</div><div class=\"answer-line\">Malignant Ventricular Tachyarrhythmia (VT/VF)</div><div class=\"answer-line\">Acute RV failure with loss of preload</div><div class=\"answer-line\">Congestive Cardiac Failure from Lateral Wall dysfunction</div><div class=\"answer-line\">Acute Mitral Regurgitation from Rupture Anterolateral Chordae</div><div class=\"answer-line\">Worsening Angina</div><div class=\"answer-line\">Ventricular Free wall rupture</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Clopidogrel or Ticagrelor 300 /180</div><div class=\"answer-line\">Analgesia – IV Morphine 2.5mg repeat to comfort</div><div class=\"answer-line\">Heparin 60u/kg up to 5000u IV</div><div class=\"answer-line\"><strong>Interventional Cardiology to facilitate reperfusion </strong></div><div class=\"answer-line\">IV Fluid load or Adrenaline infusion to achieve MAP &gt;65</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"A 23 year old woman has presented with low abdominal pain and vaginal bleeding. She had a\npositive urine pregnancy test one week ago. You are considering the differential diagnoses of miscarriage and ectopic pregnancy.","parts":[{"id":"a","label":"Part A","prompt":"List 4 historical risk factors for ectopic pregnancy. (4 marks)\n1) 2) 3) 4)"},{"id":"b","label":"Part B","prompt":"State 4 features from your history or examination that would support the diagnosis of\nmiscarriage. (4 marks) 1) 2) 3) 4) You have decided to arrange an USS as part of your assessment. The beta-HCG level is 2500 IU/L."},{"id":"c","label":"Part C","prompt":"List 4 signs on USS that would be consistent with the diagnosis of ectopic pregnancy.\n(4 marks) 1) 2) 3) 4)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Previous ectopic</div><div class=\"answer-line\">Assisted Fertility</div><div class=\"answer-line\">Prior pelvic surgery</div><div class=\"answer-line\">Hx PID</div><div class=\"answer-line\">Presence IUD</div><div class=\"answer-line\">Endometriosis</div><div class=\"answer-line\">Maternal age &gt;35</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Passage of products of conception</div><div class=\"answer-line\">Heavy Bleeding</div><div class=\"answer-line\">Known intrauterine gestation on previous USS</div><div class=\"answer-line\">Absence of lateralising pain</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Free fluid in pelvis</div><div class=\"answer-line\">Complex adnexal mass</div><div class=\"answer-line\">Hyperechogenic tubal ring</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 48 year old man has presented with a swollen left knee.\nExamination reveals a large joint effusion.","parts":[{"id":"a","label":"Part A","prompt":"List 4 potential causes. For each, state the investigative finding that would confirm the\ndiagnosis and a specific component of management. (12 marks) Cause Investigative finding Management"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Management</td><td></td></tr><tr><td>Gout</td><td>Negatively birefringent Urate Colchicine 1-2 tabs q12 hrly</td></tr><tr><td>crystals on aspirate</td><td>Or Steroids</td></tr><tr><td>Pseudogout</td><td>Calcium pyrophosphate Analgesia (accept anything</td></tr><tr><td>crystals on aspirate</td><td>reasonable)</td></tr><tr><td>Septic Arthritis</td><td>Positive Gram stain Theatre for washout (IV Abx</td></tr><tr><td>not accepted in isolation)</td><td></td></tr><tr><td>Haemarthrosis</td><td>Frank blood on aspirate Conservative (accept any of)</td></tr><tr><td>Aspirate for comfort</td><td></td></tr><tr><td>Compression</td><td></td></tr><tr><td>Non-weight bearing</td><td></td></tr><tr><td>Reverse coagulopathy</td><td></td></tr><tr><td>Manage traumatic cause where</td><td></td></tr><tr><td>appropriate</td><td></td></tr><tr><td>Other findings are not CONFIRMATORY – would accept Dual Energy CT with positive crystals for Gout</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 45 year old woman has presented with a severe headache.\nA slice of a CT scan of her head is provided below.","parts":[{"id":"a","label":"Part A","prompt":"List 3 abnormalities on the CT scan. (3 marks)\n1) 2) 3)"},{"id":"b","label":"Part B","prompt":"What is the most likely underlying pathology causing this presentation? (1 mark) You have been alerted to a deterioration in the patient’s level of consciousness. The patient has the following vital signs:\n\nGCS\nE1 V2 M4 Pulse 110 /min\n\nBP\n190/100 mmHg\n\nRR\n/min O2 sats 99% 6L O2 via Hudson mask\n\nTemp\n36.5 degrees"},{"id":"c","label":"Part C","prompt":"List 6 potential causes for this deterioration. (6 marks)\n1) 2) 3) 4) 5) 6)"},{"id":"d","label":"Part D","prompt":"List 6 components of your management including end-points where appropriate.\n(6 marks) 1) 2) 3) 4) 5) 6)"}],"propPages":["asset:img47a70dbece8d3e5672"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Subarachnoid blood in Rt temporal cortical and subcortical regions and along anterior falx</div><div class=\"answer-line\">Loss of sulci cf raised pressure</div><div class=\"answer-line\">Dilation of ventricles cf hydrocephalus</div><div class=\"answer-line\">Would not accept loss of Grey-white or M/L shift here</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Aneurysmal Subarachnoid haemorrhage</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Seizure</div><div class=\"answer-line\">Hydrocephalus with impaired brainstem perfusion</div><div class=\"answer-line\">Re-bleed</div><div class=\"answer-line\">Vasospasm with 2ary ischaemia</div><div class=\"answer-line\">Iatrogenesis from excess opiates</div><div class=\"answer-line\">Hypercapnoeic resp failure from hypoventilation (drugs or raised ICP)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Repeat CT</div><div class=\"answer-line\"><strong>Intubate </strong></div><div class=\"answer-line\">Optimise ventilation suitable target ie PaCO2 35</div><div class=\"answer-line\">Nimodipine NGT or Infusion</div><div class=\"answer-line\">BP control with suitable agent to target &lt;160</div><div class=\"answer-line\">One mark for supportive cares/ICP management (ie Na, Head up etc)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 45 year old woman has re-presented to the ED with a painful ankle. She had been seen 2 days ago after a fall and was diagnosed with an ankle sprain. Assessment today has revealed a Weber C fracture requiring surgical fixation. The patient is upset about the missed diagnosis and would like to speak to “the person in charge”. Your registrar has approached you for help.","parts":[{"id":"a","label":"Part A","prompt":"List 6 potential factors that could lead to this error. (6 marks)\n1) 2) 3) 4) 5) 6)"},{"id":"b","label":"Part B","prompt":"State 6 components of your management of this situation. (6 marks)\n1) 2) 3) 4) 5) 6)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Medical error – knowledge deficit by initial doctor</div><div class=\"answer-line\">Lack of senior supervision/review of patient prior to discharge</div><div class=\"answer-line\">Lack of process regarding xray review by seniors</div><div class=\"answer-line\">Delay to xr reporting</div><div class=\"answer-line\">Lack of notification from radiology re: abnormal imaging</div><div class=\"answer-line\">Departmental factors – busy department, understaffing, sick leave etc</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Arrange appropriate care – contact orthopaedics</div><div class=\"answer-line\">Ensure analgesia/immobilsation adequate</div><div class=\"answer-line\">Open disclosure – apologise about initial miss</div><div class=\"answer-line\">Assist patient with complaints process</div><div class=\"answer-line\">Pledge to investigate issues leading to initial error</div><div class=\"answer-line\">Investigate initial presentation – review notes, speak to involved parties</div><div class=\"answer-line\">Inform patient that you will notify of the outcomes of investigation</div><div class=\"answer-line\">Review departmental processes where appropriate re: radiology, senior supervision and review prior</div><div class=\"answer-line\">to discharge</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"An 11 year old boy has presented after falling off a swing in the playground at school.\nHis x-rays are provided below.","parts":[{"id":"a","label":"Part A","prompt":"State 3 radiographical abnormalities and provide the injury classification. (4 marks)\n1) 2) 3) Injury classification"},{"id":"b","label":"Part B","prompt":"State 4 components of your management. (4 marks)\n1) 2) 3) 4)"},{"id":"c","label":"Part C","prompt":"List 3 specific complications of this injury. (3 marks)\n1) 2) 3)"}],"propPages":["asset:imgbc2912d80282374adf"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Physeal fracture of distal radius</div><div class=\"answer-line\">80% dorsal displacement</div><div class=\"answer-line\">20% lateral displacement</div><div class=\"answer-line\">30 deg dorsal angulation</div><div class=\"answer-line\">Fracture extends into metaphysis at dorsal margin of physis</div><div class=\"answer-line\">Classification</div><div class=\"answer-line\"><strong>Salter-Harris II </strong>distal Radius<strong> </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Analgesia</div><div class=\"answer-line\">Consent for Procedural Sedation</div><div class=\"answer-line\">Procedural Sedation to facilitate reduction</div><div class=\"answer-line\">Closed reduction and immobilization in some kind of forearm plaster ie radial gutter slab</div><div class=\"answer-line\">Referral to orthopaedics for follow up</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Growth arrest from physeal failure</div><div class=\"answer-line\">Median neuropathy</div><div class=\"answer-line\">EPL tendon injury</div><div class=\"answer-line\">Malunion and deformity</div><div class=\"answer-line\">Reflex Sympathetic Dystrophy (CRPS)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"A 45 year old man has presented with severe low back pain and fever.\nYou are considering the diagnosis of epidural abscess.","parts":[{"id":"a","label":"Part A","prompt":"List 4 risk factors for epidural abscess. (4 marks)\n1) 2) 3) 4)"},{"id":"b","label":"Part B","prompt":"List 4 examination findings that would be consistent with cauda equina syndrome.\n(4 marks) 1) 2) 3) 4) Your history and examination are concerning for epidural abscess."},{"id":"c","label":"Part C","prompt":"List 4 investigations you would perform, with justification. (4 marks)\nInvestigation Justification\nPAH 2021.1 trial SAQ paper\nPART 2\nQuestions 10 - 18\n1 hour"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Diabetes</div><div class=\"answer-line\">Alcoholics</div><div class=\"answer-line\">HIV</div><div class=\"answer-line\"><strong>IVDU </strong></div><div class=\"answer-line\">Recent Spinal Instrumentation/Surgery</div><div class=\"answer-line\">Adjacent Infection</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Saddle anaesthesia</div><div class=\"answer-line\">Lower limb weakness</div><div class=\"answer-line\">Palpable bladder</div><div class=\"answer-line\">Bilateral LL weakness or paraesthesia</div><div class=\"answer-line\">Decreased/absent LL reflexes</div><div class=\"answer-line\">Decreased rectal tone</div><div class=\"answer-line\">Decreased/absent bulbocavernosus/anal wink</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Blood cultures to rationalize antimicrobials</div><div class=\"answer-line\">CRP – often raised prior to other inflamm markers</div><div class=\"answer-line\">Other tests accepted if well justified:</div><div class=\"answer-line\">ECHO – if murmur and suspected endocarditis as source</div><div class=\"answer-line\">Chem20 – if suspected renal dysfunction to guide antimicrobial dosing</div><div class=\"answer-line\">Platelets or COAGs if signs CLD or on anticoagulants to inform operative interventions</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 14 year old female has presented to the ED after an episode of deliberate self-harm. She has cut her left wrist with a knife. A clinical photograph is provided below.","parts":[{"id":"a","label":"Part A","prompt":"List 3 descriptive features of the wound. (3 marks)\n1) 2) 3)"},{"id":"b","label":"Part B","prompt":"In the following table, state the examination findings that would be consistent with damage to the listed structures. (5 marks)"},{"id":"c","label":"Part C","prompt":"List 3 tendons that might be injured. For each, state the examination findings that would\n\nbe consistent with such an injury. (6 marks)\nTendon Examination findings The patient’s mother is concerned that her daughter has been injecting methamphetamines."},{"id":"d","label":"Part D","prompt":"List 5 features of your assessment (other than agitation) that would suggest current\nmethamphetamine intoxication. (5 marks) 1) 2) 3) 4) 5) Shortly after your assessment, the patient becomes extremely agitated and is attempting to leave. It is clear that she is currently experiencing methamphetamine intoxication. You have assessed her wound as requiring inpatient surgical management."},{"id":"e","label":"Part E","prompt":"State 5 components of your overall management of this patient. (5 marks)\n1) 2) 3) 4) 5)"}],"propPages":["asset:img1be2f5f0d01e297d20"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Transverse laceration across entire forearm</div><div class=\"answer-line\">Just proximal to wrist crease</div><div class=\"answer-line\">Penetrates deep to superficial fascia</div><div class=\"answer-line\">Gaping with deep structures on view</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Radial Artery:</div><div class=\"answer-line\">Absent/decreased perfusion of hand</div><div class=\"answer-line\">Loss of pulse distal to laceration</div><div class=\"answer-line\">Pulsatile haemorrhage</div><div class=\"answer-line\">Medial N</div><div class=\"answer-line\">Sensory: Lateral 3½ digits on volar aspect (thenar eminence is non-variable)</div><div class=\"answer-line\">Motor: Any description of loss of function of FPB, Abd PB, Opp P, loss 1st/2nd lumbricals</div><div class=\"answer-line\">Ulnar N:</div><div class=\"answer-line\">Sensory: hypothenar eminence, medial 1½ digits</div><div class=\"answer-line\">Motor: 3rd and 4th lumbricals, interossei, adductor pollicis, abductor digiti minimi, flexor digiti minimi,</div><div class=\"answer-line\">opponens digiti minimi</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Flexor carpi radialis: weakness of flexion and abduction of wrist</td><td>Flexor Carpi Ulnaris: weakness of flexion and adduction of wrist</td></tr><tr><td>Palmaris Longus: no findings of note</td><td>Flexor digitorum superficialis: weakness of flexion at PIPJ</td></tr><tr><td>Flexor Digitorum Profundus weakness of flexion at DIPJ</td><td>Flexor Pollicis Longus : flexes IPJ of thumb and assists wrist flexion – weakness of this (FPB persists)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Features of methamphetamine intoxication:</div><div class=\"answer-line\">Anxiety</div><div class=\"answer-line\">Pressured speech</div><div class=\"answer-line\">Tremor</div><div class=\"answer-line\">Choreiform movements</div><div class=\"answer-line\">Hallucinations</div><div class=\"answer-line\">Compulsive behaviours ie skin picking</div><div class=\"answer-line\">Tachycardia</div><div class=\"answer-line\">Hypertension</div><div class=\"answer-line\">Diaphoresis</div><div class=\"answer-line\">Mydriasis</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\"><strong>Detain under guardianship</strong> as lacking capacity due to intoxication</div><div class=\"answer-line\">Sedation for patient and staff safety – ie Droperidol 10mg IM/IV</div><div class=\"answer-line\"><strong>Orthopaedic </strong>or Plastics admission for wound repair</div><div class=\"answer-line\">Tetanus Immunisation</div><div class=\"answer-line\"><strong>Antibiotics – IV Cephazolin 1gm or equivalent </strong></div><div class=\"answer-line\">Analgesia – something sensible</div><div class=\"answer-line\">Splinting/Immobilisation</div><div class=\"answer-line\">Discussion with mother re: planned intervention/consent</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 40 year old woman has presented to the ED with a 2 day history of right flank pain with fevers and chills. Your assessment is consistent with pyelonephritis.","parts":[{"id":"a","label":"Part A","prompt":"List 4 potential indications for performing imaging of the urinary system. (4 marks)\n1) 2) 3) 4) The patient requires admission for intravenous antibiotics. Imaging was performed and did not demonstrate any additional complications."},{"id":"b","label":"Part B","prompt":"List 4 antibiotic regimens you might prescribe for this patient. For each, state the\nappropriate clinical indication. (4 marks) Antibiotic regimen Clinical indication Shortly after antibiotic administration, the patient has developed a rash. The patient has the following vital signs:\n\nGCS\nE4 V4 M6 Pulse 140 /min\n\nBP\n75/40 mmHg\n\nRR\n/min O2 sats 89% room air"},{"id":"c","label":"Part C","prompt":"State 4 components of your management. (4 marks)\n1) 2) 3) 4)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Shock</div><div class=\"answer-line\">New renal impairment</div><div class=\"answer-line\">Hx Renal calculi</div><div class=\"answer-line\">Failure of outpatient management</div><div class=\"answer-line\">Single kidney</div><div class=\"answer-line\">Hx Immunosuppression (accept diabetes)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Amp + Gent : for severe pyelo</td><td>Gent contraindicated: Ceftriaxone</td></tr><tr><td>Pen Hypersensitivity: Gent alone</td><td>Known ESBL: Meropenem</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">IV Fluid 1000ml stat</div><div class=\"answer-line\">Cease offending Abx, alter antimicrobial regime for subsequent dose and record allergy</div><div class=\"answer-line\">Steroids – IV HCT 4mg/kg or 200mg</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 12 year old boy has presented with a sore throat for the past 4 days.\nA clinical photograph is provided below.","parts":[{"id":"a","label":"Part A","prompt":"State your diagnosis, supported by four descriptive features. (5 marks) Diagnosis Descriptive features 1) 2) 3) 4) The patient has the following vital signs:\n\nGCS\nPulse 100 /min\n\nBP\n120/75 mmHg\n\nRR\n/min O2 sats 100% room air Temperature 38.5 degrees"},{"id":"b","label":"Part B","prompt":"State 3 components of your management. (3 marks)\n1) 2) 3) After several hours in the ED, a nurse has asked you to review the patient as she is concerned about the patient’s airway."},{"id":"c","label":"Part C","prompt":"List 4 findings of your assessment of the patient’s airway that would lead to concern about the need for urgent intervention. (4 marks) 1) 2) 3) 4)"}],"propPages":["asset:imgd92a183f42249e2c42"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Erythematous, exudative, assymetrical fullness of soft palate with uvular deviation</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Analgesia – anything sensible (drug, route, dose)</div><div class=\"answer-line\">Antibiotics – IV BenzylPenicillin 50mg/kg Q6h</div><div class=\"answer-line\">Steroid – dexamethasone IV 0.15mg/kg up to 8mg</div><div class=\"answer-line\"><strong>ENT attendance</strong> for drainage (accept ED aspiration)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Drooling</div><div class=\"answer-line\">Inability to speak</div><div class=\"answer-line\">Stridor</div><div class=\"answer-line\">Hypoxia</div><div class=\"answer-line\">Posturing (ie tri-pod) – unable to lie flat</div><div class=\"answer-line\">Agitation</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 30 year old man has been brought to the ED after falling off a high ladder while working as a painter. His pelvis x-ray is provided below.","parts":[{"id":"a","label":"Part A","prompt":"List 3 abnormalities on the x-ray. (3 marks)\n1) 2) 3)"},{"id":"b","label":"Part B","prompt":"List 3 potential injuries (other than vascular) directly associated with the pelvic injury demonstrated. For each, state a clinical sign that would support its presence. (6 marks) Associated injury Supportive clinical sign Comprehensive imaging has revealed no other injuries. The patient has active arterial bleeding from a pelvic vessel demonstrated on CT angiogram.\nHis vital signs are:\n\nGCS\nE4 V4 M6 Pulse 135 /min\n\nBP\n70/40 mmHg\n\nRR\n/min O2 sats 100 % 15L O2 via non re-breather mask"},{"id":"c","label":"Part C","prompt":"State 3 components of your further management of this patient. (3 marks)\n1) 2) 3)"}],"propPages":["asset:imgdf250f977d1f8b7af5"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Rt Superior/Inferior Rami # with significant displacement</div><div class=\"answer-line\">Left Superior/Inferior Rami #</div><div class=\"answer-line\"><strong>Opening anterior elements Rt SIJ </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Bowel Injury : PR Blood</td><td>Urethral Injury: Blood at meatus, boggy perineal haematoma</td></tr><tr><td>Lumbo-Sacral Nerve Injury: LL weakness, focal neuro deficits</td><td>Bladder Injury: Haematuria w/o perineal signs</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>Blood transfusion</strong> – ROTEM guided or equiv, SBP &gt;80</div><div class=\"answer-line\">TXA 1gm + infusion</div><div class=\"answer-line\"><strong>Interventional Radiology</strong> for embolization</div><div class=\"answer-line\">Accept pelvic binder given SIJ opening</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"A 75 year old woman has presented with palpitations and shortness of breath.\nHer ECG is provided below.","parts":[{"id":"a","label":"Part A","prompt":"State the rhythm abnormality shown, with 3 significant ECG features. (4 marks) Rhythm abnormality Significant ECG features 1) 2) 3)"},{"id":"b","label":"Part B","prompt":"List 4 medications you could use to manage this problem, including doses. For each,\nprovide a specific clinical circumstance for its use. (8 marks) Medication Clinical circumstance"}],"propPages":["asset:imgf35822e7beaebd0ef5"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Supportive features:</div><div class=\"answer-line\">Regular narrow complex tachycardia</div><div class=\"answer-line\">Regular Flutter P waves at 300/min</div><div class=\"answer-line\">Regular QRS complexes at 150/min</div><div class=\"answer-line\">Fixed A:V relationship</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Metoprolol IV 2.5mg aliquots – symptomatic, no heart failure</td><td>Amiodarone 5mg/kg over 30min – known structural heart disease/CHF, signs of decompensation,</td></tr><tr><td>aiming for rhythm control, onset &lt;48h</td><td>Verapamil 5mg IV aliquots – same as B-blocker, unable to have B-blocker</td></tr><tr><td>Digoxin 500mcg PO/IV – rate control in known CCF/poor LV Function</td><td>Flecainide 2mg/kg – structurally normal heart, intolerance of tachycardia, &lt;48h, aiming for rhythm</td></tr><tr><td>control</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 75 year old man has presented with sudden painless loss of vision in his right eye.","parts":[{"id":"a","label":"Part A","prompt":"List 4 potential causes of this problem. For each, state a predisposing medical condition\nand the cardinal examination finding/s. (12 marks) Cause Predisposing medical condition Cardinal Examination finding/s"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>CRAO:  AF, ICA plaque ; pale retina with cherry red spot</td><td>CRVO: Hypertension, diabetes, atherosclerosis; blood and thunder retina</td></tr><tr><td>Retinal Detachment: age, myopia; corrugated retina, focal change with visible transition to normal</td><td>retina</td></tr><tr><td>Retinal Haemorrhage: hypertension, diabetes, atherosclerosis; retinal haemorrhage</td><td>Vitreal Haemorrhage: trauma; obscured retina</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 45 year old man has presented to the ED with right upper quadrant abdominal pain.\nHe had a liver transplant 5 years ago for primary biliary cirrhosis.","parts":[{"id":"a","label":"Part A","prompt":"List 6 key differential diagnoses. For each, provide a cardinal assessment finding (history, examination or investigation) that would support the diagnosis. (12 marks) Differential diagnosis Assessment finding"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Portal Vein/Hepatic Vein Thrombosis: no flow on USS</td><td>Alcoholic Hepatitis: History alcohol binge</td></tr><tr><td>Pancreatitis: elevated lipase</td><td><strong>Transplant rejection</strong>: jaundice, tender, raised LFTs</td></tr><tr><td>Right Lower Lobe Pneumonia: crackles on exam</td><td><strong>Cholangitis from CBD stricture</strong>/obstrution: dilated intra- and extra- hepatic ducts</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 28 year old woman has presented after taking a deliberate overdose of aspirin.","parts":[{"id":"a","label":"Part A","prompt":"List 5 findings on history or examination that would be consistent with salicylate toxicity. (5 marks) 1) 2) 3) 4) 5) After a short time in the ED, a venous blood gas has been taken. The result is provided below.\n\npH\n7.44 (7.35 - 7.45)\n\npCO2\nmmHg (35 - 45)\n\npO2\nmmHg\n\nBE\n-14.0 mmol/L (-3.0 - 3.0)\n\nHCO3\nmmol/L (18 - 27)\n\nNa\n142 mmol/L (133 - 144)\n\nK\n3.3 mmol/L (3.3 - 4.9)\n\nCl\n114 mmol/L (97 - 110)"},{"id":"b","label":"Part B","prompt":"State 3 acid -base abnormalities. Include the biochemical evidence for each. (6 marks)\nAcid-base abnormality Evidence"},{"id":"c","label":"Part C","prompt":"List 2 methods of treatment for salicylate toxicity. Include the indications for each.\n(2 marks) 1) 2)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Nausea and Vomiting</div><div class=\"answer-line\">Tinnitus</div><div class=\"answer-line\">Tachypnoea</div><div class=\"answer-line\">Agitation</div><div class=\"answer-line\">Seizures</div><div class=\"answer-line\">Hyperthermia</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Respiratory Alkalosis – low CO2</td><td>HAGMA – Anion Gap 18 BE elevated</td></tr><tr><td>Concurrent NAGMA – Delta Gap – 6/14 = predominant NAGMA ?excess chloride</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Urinary Alkalinisation – any symptomatic patients</td><td>Dialysis – Severe toxicity (ALOC, renal failure), Urinary Alk not feasible</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 92 year old man has been brought to the ED with abnormal behaviour. He was noticed to be confused whilst walking around the shops. The patient has multiple bruises of varying ages on his head, consistent with recent falls. You have elected to perform a CT scan of his head to exclude intracranial haemorrhage. The patient is significantly agitated and will require sedation to enable the CT scan to be performed.","parts":[{"id":"a","label":"Part A","prompt":"List 4 potential complications of providing sedation to facilitate the CT scan. For each,\nstate your strategy to prevent patient harm. (8 marks) Complication Preventative strategy Your assessment has revealed no injuries. The patient’s agitation has been attributed to minor alcohol intoxication and has settled with observation only. The patient lives alone. The patient’s daughter has described him being a bit more forgetful lately."},{"id":"b","label":"Part B","prompt":"List 3 allied health services you might engage in his further assessment. For each, state\nyour rationale for their involvement. (3 marks) 1) 2) 3)\nPAH 2021.1 trial SAQ paper\nPART 3\nQuestions 19 - 27\n1 hour"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Respiratory Depression – use minimum dose required to achieve safe restraint, employ physical</td><td>straps to keep patient still, use agent least likely to suppress resp drive</td></tr><tr><td>Loss of airway protective reflexes and aspiration risk – administer antiemetic and position patient in</td><td>lateral position if possible</td></tr><tr><td>Hypoxia from loss of resp drive – administer supplemental O2</td><td>Hypotension from sedative agent – cautious dose, choice of agent</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Social Work – to explore options re: emergency respite,  supports for family and carers</td><td>Community Interface Nurse – home services, offer support groups, aged-care assessment referrals</td></tr><tr><td>etc</td><td>Occupational Therapy – organize in-home assessment for mobility aids, high-risk areas etc</td></tr><tr><td>Pharmacy – medication rationalization, assistance with aids ie webster pack</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A 2 year old boy has been brought to the ED with a rash of the lower limbs that has been present for 3 days. A clinical photograph is provided below.","parts":[{"id":"a","label":"Part A","prompt":"List 4 features of this rash. (4 marks)\n1) 2) 3) 4) Examination reveals a well child with normal vital signs."},{"id":"b","label":"Part B","prompt":"List and justify 4 investigations you might perform. (4 marks)"},{"id":"c","label":"Part C","prompt":"State the most likely diagnosis and list 3 complications of this disease. (4 marks) Diagnosis Complications 1) 2) 3)"}],"propPages":["asset:img2e94306d127b9ddcdc"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Maculopapular</div><div class=\"answer-line\">Diffuse to both legs</div><div class=\"answer-line\">Appears to be haemorrhagic – mixed sizes between petechiae, ecchymoses</div><div class=\"answer-line\">Relative sparing of flexoral creases</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">FBE – check platelets to exclude ITP</div><div class=\"answer-line\">Chem20 – check renal function</div><div class=\"answer-line\"><strong>Urinalysis </strong>for proteinuria</div><div class=\"answer-line\">Urine Micro for casts</div><div class=\"answer-line\">Anything to exclude leukaemia ie blood film</div><div class=\"answer-line\">Tests for Strep ie ASOT, AntiDNAaseB</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Intussusception</div><div class=\"answer-line\">Glomerulonephritis</div><div class=\"answer-line\">Renal Failure</div><div class=\"answer-line\">GIT haemorrhage</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"A 40 year old alcoholic man has been brought to the ED after being found on the floor of his home. He has not been seen for several days.","parts":[{"id":"a","label":"Part A","prompt":"State 5 distinct components of your examination of this patient. Provide justification for each. (5 marks) 1) 2) 3) 4) 5) A venous blood gas has been provided below.\n\npH\n7.54 (7.35 - 7.45)\n\npCO2\nmmHg (35 - 45)\n\nHCO3\nmmol/L (22 - 32)\n\nNa\n104 mmol/L (135 - 145)\n\nK\n8.6 mmol/L (3.5 - 5.2)\n\nCl\nmmol/L (95 - 110)\n\nGlucose\n5.7 mmol/L (3.0 - 7.8)"},{"id":"b","label":"Part B","prompt":"State the main metabolic acid-base abnormality, including the most likely cause. (2 marks) Abnormality Cause"},{"id":"c","label":"Part C","prompt":"Interpret the respiratory acid-base status, including any relevant calculations. (2 marks) Interpretation Calculations"},{"id":"d","label":"Part D","prompt":"Provide the details for the additional acid-base disturbance, including any calculations\nperformed. Provide 3 potential causes for this disturbance. (5 marks)\nAcid-base disturbance Calculations Potential causes 1) 2) 3) The patient is hyponatraemic at a level of 104 mmol/L."},{"id":"e","label":"Part E","prompt":"Regarding this result, complete the following responses: Likely cause (1 mark) Emergency complication associated with this abnormality (1 mark) Acute management of above stated emergency complication (3 marks) The patient is hyperkalaemic at a level of 8.6 mmol/L."},{"id":"f","label":"Part F","prompt":"Regarding this result, complete the following responses: Likely cause (1 mark) Emergency complication associated with this abnormality (1 mark) 3 components of your management of above stated emergency complication (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>Vital signs</strong> for shock, dehydration</td><td>Evidence of Head Injury  – may indicate sign of trauma consequent to fall, or primary cause</td></tr><tr><td>Chest for signs of aspiration</td><td>Skin for pressure sores</td></tr><tr><td><strong>Dependent areas</strong> for compartment concerns</td><td>Mucous membranes for hydration status</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Metabolic Alkalosis</div><div class=\"answer-line\">Cause: likely from vomiting</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Complete respiratory compensation</div><div class=\"answer-line\">0.7 x HCO3 + 20 = 31 + 20 = same as measured</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">HAGMA – Anion Gap 19</div><div class=\"answer-line\">Causes – renal failure (most likely), ketoacids from alcoholism, lactate from liver failure and impaired</div><div class=\"answer-line\">metabolism</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Vomiting (accept dietary deficiency)</div><div class=\"answer-line\">Complication: cellular swelling and cerebral oedema leading to seizures and obtundation</div><div class=\"answer-line\">3% saline (one mark)  (3mls/kg – one mark)) to clinical end-point (ie resolution seizure or improved</div><div class=\"answer-line\">mentation) (one mark)</div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"answer-line\">Renal failure from rhabdomyolysis</div><div class=\"answer-line\">Cardiac arrhythmia (bradycardia)</div><div class=\"answer-line\"><strong>cardioprotection </strong>(10-30mls Cal Gluconate) end-point normalization of QRS duration</div><div class=\"answer-line\">Shifting drugs: (2 of)</div><div class=\"answer-line\">Accept salbutamol -5-10mg nebulised</div><div class=\"answer-line\">NaHCO3 – 1-2mmol/kg</div><div class=\"answer-line\">Insulin – 10u IV actrapid</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"A 25 year old man presents with left knee pain after being tackled during a football match.","parts":[{"id":"b","label":"Part B","prompt":"State the 2 main abnormalities in the x-rays. (2 marks)\n1) 2)"},{"id":"c","label":"Part C","prompt":"List 2 commonly associated ligamentous injuries. (2 marks)\n1) 2)"},{"id":"d","label":"Part D","prompt":"List 2 non-ligamentous structures that might be injured. Provide a confirmatory\nexamination finding for each. (4 marks) Structure Confirmatory examination finding"},{"id":"e","label":"Part E","prompt":"State 3 components of your management of this patient. (3 marks)\n1) 2) 3)"}],"propPages":["asset:img9a56866d2c74e8c034","asset:img55daefbc1b50bb3dc1"],"questionPages":[],"answerPages":[],"removedNonQuestionResponseFragments":["rays of his knee are provided below."],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Tibial Plateau fracture</div><div class=\"answer-line\">Lipohaemarthrosis</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">MCL</div><div class=\"answer-line\">ACL</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Patellar Tendon: Loss of extensor mechanism</td><td>Lateral Meniscus: Locking knee joint</td></tr><tr><td>Hamstrings tendon: Pain to posterior thigh</td><td>Common peroneal nerve: loss of eversion/dorsiflexion</td></tr><tr><td>Popliteal artery : decreased perfusion/pulses into lower leg</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Analgesia</div><div class=\"answer-line\">Non-weight bearing</div><div class=\"answer-line\">Immobilisation/Splinting</div><div class=\"answer-line\">Orthopaedic review for Operative repair</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"A 22 year old man has been taken to the ED after a high speed motor vehicle accident.\nA chest x-ray has been performed on arrival and is provided below.","parts":[{"id":"a","label":"Part A","prompt":"List 3 injuries shown on the x-ray. For each, provide your management strategy. (6 marks)\nInjury Management strategy The patient has a normal pelvic x-ray and a negative FAST scan. There are no long bone fractures and no external bleeding.\nHis vital signs are as follows:\n\nGCS\nE3 V4 M6 Pulse 130 /min\n\nBP\n80/55 mmHg\n\nRR\n/min O2 sats 90% 15L via non-rebreather mask You have decided to proceed with intubation as part of your further management."},{"id":"b","label":"Part B","prompt":"State 4 changes from a standard rapid sequence induction that you will employ. Provide a\nbrief rationale for each change. (4 marks) 1) 2) 3) 4)"}],"propPages":["asset:img022e51e9fc5b8df142"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>Diaphragmatic Rupture</strong>: NGT insertion, referral for operative repair</td><td>Left Haemothorax; ICC (careful insertion given diaphragmatic injury)</td></tr><tr><td>Multiple Lt rib fractures: analgesia, PCA, ?intercostal blocks</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Decreased dose of induction agent – Ketamine 0.5mg/kg to mitigate haemodynamic depression</td><td>Hi-Flow Oxygen throughout induction – NP O2 @ 15lpm + BVM @ 15lpm through induction/apnoea</td></tr><tr><td>Avoid apnoea – bag through induction to avoid acidosis and hypoxia</td><td>Fluid load to counter vasodilation – 1u PRBCs during induction</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"A 55 year old woman has presented with severe chest pain and difficulty breathing.\nTwo slices from a CT scan of her chest are provided below.","parts":[{"id":"a","label":"Part A","prompt":"State 3 findings from the CT scans and provide a clinical conclusion. (4 marks)\nFindings 1) 2) 3) Clinical implication of radiological abnormalities"},{"id":"b","label":"Part B","prompt":"List 3 other investigations you would perform. Provide justification for each. (3 marks)\n1) 2) 3) On examination, the patient has the following vital signs:\n\nGCS\nE4 V4 M6 Pulse 140 /min\n\nBP\n78/45 mmHg\n\nRR\n/min O2 sats 88% room air"},{"id":"c","label":"Part C","prompt":"State 4 features of your management of this patient. (4 marks)\n1) 2) 3) 4)"}],"propPages":["asset:img6983804b55130a7097","asset:imge75ebe0016b6506e78"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Bilateral proximal pulmonary emboli</div><div class=\"answer-line\">Dilated pulmonary trunk</div><div class=\"answer-line\">RV &gt;LV</div><div class=\"answer-line\">LV septum flattened</div><div class=\"answer-line\">PE with raised Right-sided pressures (accept Massive/Submassive)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>ECHO: assess Right sided pressures and RV function</td><td>Venous Blood Gas: evidence of impaired perfusion ie HAGMA</td></tr><tr><td>Prothrombotic screen: identify underlying cause</td><td>Troponin: carries prognostic significance</td></tr><tr><td>ECG: signs RV strain</td><td>Others:</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Fluid Load with SBP &gt;100</div><div class=\"answer-line\">Oxygenation aim Sats &gt;94%</div><div class=\"answer-line\">Heparin</div><div class=\"answer-line\">Analgesia</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"A 3 year old boy has been brought to the ED by ambulance after being found submerged in a\nbackyard pool. He was intubated on scene.","parts":[{"id":"a","label":"Part A","prompt":"List 5 historical features of the event you will seek. Explain the relevance of each.\n(5 marks) 1) 2) 3) 4) 5)"},{"id":"b","label":"Part B","prompt":"List 4 complications of near drowning that you would seek to identify in the ED. (4 marks) 1) 2) 3) 4) The child died in the ED. Several staff are visibly upset by the case."},{"id":"c","label":"Part C","prompt":"State 3 key aspects of debriefing in the Emergency Department. (3 marks)\n1) 2) 3)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Duration of submersion</div><div class=\"answer-line\">Time to life-support</div><div class=\"answer-line\">Initial rhythm</div><div class=\"answer-line\">Details and duration of ACLS</div><div class=\"answer-line\">GCS on arrival to ED</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Trauma – head or C-spine</div><div class=\"answer-line\">Aspiration</div><div class=\"answer-line\">Hypothermia</div><div class=\"answer-line\">Hypoglycaemia</div><div class=\"answer-line\">Hypoxic Brain Injury</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Voluntary</div><div class=\"answer-line\">Contemporaneous</div><div class=\"answer-line\">Non-judgemental</div><div class=\"answer-line\">Open discourse encouraged</div><div class=\"answer-line\">People should be encouraged to share emotions without solutions being sought</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"You are undertaking a morning short stay ward round. You are seeing a 67 year old man who was brought to the ED overnight with behavioural disturbance and found to be intoxicated with alcohol. On your review, the patient is confused and mildly agitated.","parts":[{"id":"a","label":"Part A","prompt":"List 6 potential causes of this patient’s confusion. For each, state a supportive finding\nfrom history or examination. (12 marks) Cause of confusion Supportive finding - history or examination"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Alcohol withdrawal: generalized tremor</td><td>Hyponatraemia: obtundation</td></tr><tr><td>Intracranial Trauma: signs of external trauma</td><td>Wernicke’s Encephalopathy: opthalmoplegia</td></tr><tr><td>Hepatic Encephalopathy: jaundice</td><td>Delirium: fever</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"A 10 month old girl has been taken to ED after a brief seizure in the community.","parts":[{"id":"a","label":"Part A","prompt":"List 4 potential causes of the seizure. For each, list a key supportive feature of your\nassessment (history, examination, bedside investigation). (8 marks) Cause Supportive feature Shortly after arrival, the patient has another seizure. Despite initial supportive care and 2 doses of intravenous midazolam, the seizure continues."},{"id":"b","label":"Part B","prompt":"List 4 other drugs, with doses, that you could give in an attempt to terminate the seizure. (4 marks) 1) 2) 3) 4)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Febrile convulsion: Febrile illness</td><td>Head Trauma: external signs of head trauma (ie bruising, swelling)</td></tr><tr><td>Primary Seizure Disorder ie prior seizures, congenital diagnosis, history hypoxic birth injury</td><td>Metabolic Syndrome – metabolic acidosis, abnormal facies, failure to thrive</td></tr><tr><td>Structural disorders ie Sturge-Weber</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Leviteracetam 40mg /kg</div><div class=\"answer-line\">Phenobarbitone 10-20mg/kg</div><div class=\"answer-line\">Phenytoin 20mg/kg</div><div class=\"answer-line\">Na Valproate 10mg/kg</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"A 28 year old female refugee has been brought to the ED after a collapse in the detention centre where she is being held. The patient was witnessed to collapse and have a brief period of altered consciousness. She has been on a hunger strike for the last 10 days.","parts":[{"id":"a","label":"Part A","prompt":"List 4 investigations you would perform. Provide justification for each. (4 marks)\n1) 2) 3) 4)"},{"id":"b","label":"Part B","prompt":"State 4 methods you could employ to ensure patient centred care as part of your\ndepartment’s approach to cultural safety. (4 marks) 1) 2) 3) 4) You have assessed the patient as being at significant risk of developing re-feeding syndrome."},{"id":"c","label":"Part C","prompt":"List 4 clinical features of re-feeding syndrome. (4 marks)\n1) 2) 3) 4)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>BSL – exclude nutritional deficiency</td><td>Chem20 – identify electrolytic cause</td></tr><tr><td>VBG – identify acid-base disturbance</td><td>bHCG – exclude pregnancy</td></tr><tr><td>ECG – identify arrhythmia</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Taking a cultural history</div><div class=\"answer-line\">Incorporating diverse health beliefs</div><div class=\"answer-line\">Provide access to support people according to their cultural needs</div><div class=\"answer-line\">Access to cultural and/or religious representative</div><div class=\"answer-line\">For all non-english speakers, access to professional interpreter service and information</div><div class=\"answer-line\">Feedback mechanisms available that represent cultural and language diversity</div><div class=\"answer-line\">Relationships established with primary care providers for patients of culturally diverse backgrounds</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Hypophosphataemia</div><div class=\"answer-line\">Hypokalaemia</div><div class=\"answer-line\">Hypomagnesaemia</div><div class=\"answer-line\">Hyperglycaemia</div><div class=\"answer-line\">Hyponatraemia</div><div class=\"answer-line\">Thiamine deficiency</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}]);
